import{decoder}from'tetris-fumen';import{boardFromFumenPage}from'./board.mjs';import{expandPattern}from'./pattern.mjs';import{queueCanSave}from'./saves.mjs';
const DETAIL=[['TL/TJ','TL||TJ'],['TI','TI'],['TO','TO'],['TS/TZ','TS||TZ'],['LJ','LJ'],['OI','OI'],['IL/IJ','IL||IJ'],['IS/IZ','IS||IZ'],['OL/OJ','OL||OJ'],['JS/LZ','JS||LZ'],['JZ/LS','JZ||LS'],['OS/OZ','OS||OZ'],['SZ','SZ']];
export function fourthQueues(hold,nextPair){hold=hold.toUpperCase();const pair=nextPair.toUpperCase();const remain=[...'TLJISZO'].filter(p=>!new Set(pair).has(p)).join('');return{pathPattern:`${hold},${pair[0]},${pair[1]},[${remain}]p4`,savePattern:`${hold},${pair[0]},${pair[1]},[^${pair}]p4`}}
export function calculateFourthDistribution({sourceFumen,hold,nextPair,solver,useHold=true}){const{pathPattern,savePattern}=fourthQueues(hold,nextPair),board=boardFromFumenPage(decoder.decode(sourceFumen)[0]),queues=expandPattern(pathPattern);const counts=Array(DETAIL.length).fill(0);let solved=0;for(const q of queues){const sols=solver.enumeratePc(board,q,useHold);if(sols.length)solved++;for(let i=0;i<DETAIL.length;i++)if(queueCanSave(q,sols,savePattern,DETAIL[i][1])){counts[i]++;break}}let cum=0;return{pathPattern,savePattern,total:queues.length,solved,ranks:DETAIL.map(([label,expression],i)=>{cum+=counts[i];return{label,expression,count:counts[i],cumulativeCount:cum,total:queues.length}})}}
